import{_ as p,a0 as a,w as d,s as r,ao as l,I as n,x as e,a1 as s,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"用這個開源工具在 Linux 上訪問你的 iPhone | LCTT x X-CMD","titleTemplate":false,"description":"用這個開源工具在 Linux 上訪問你的 iPhone | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用這個開源工具在 Linux 上訪問你的 iPhone | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用這個開源工具在 Linux 上訪問你的 iPhone | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210823 Access your iPhone on Linux with this open source tool","title":"用這個開源工具在 Linux 上訪問你的 iPhone","tag":"202108","desc":""},"relativePath":"202108/20210823 Access your iPhone on Linux with this open source tool.md","filePath":"[post].md"}'),u={name:"202108/20210823 Access your iPhone on Linux with this open source tool.md"};function b(h,i,m,g,c,k){const t=a("Link");return d(),r("div",null,[i[24]||(i[24]=l('<h1 id="用這個開源工具在-linux-上訪問你的-iphone" tabindex="-1">用這個開源工具在 Linux 上訪問你的 iPhone <a class="header-anchor" href="#用這個開源工具在-linux-上訪問你的-iphone" aria-label="Permalink to “用這個開源工具在 Linux 上訪問你的 iPhone”">​</a></h1><blockquote><p>通過使用 Libimobiledevice 從 Linux 與 iOS 設備進行通信。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/31/092907bc26qep3ekc73czl.jpg" alt=""></p><p>iPhone 和 iPad 絕不是開源的，但它們是流行的設備。許多擁有 iOS 備的人恰好也在使用大量的開源軟件，包括 Linux。Windows 和 macOS 的用户可以通過使用蘋果公司提供的軟件與 iOS 設備通信，但蘋果公司不支持 Linux 用户。開源程序員早在 2007 年（就在 iPhone 發佈一年後）就以 Libimobiledevice（當時叫 libiphone）來拯救了人們，這是一個與 iOS 通信的跨平台解決方案。它可以在 Linux、Android、Arm 系統（如樹莓派）、Windows、甚至 macOS 上運行。</p><p>Libimobiledevice 是用 C 語言編寫的，使用原生協議與 iOS 設備上運行的服務進行通信。它不需要蘋果公司的任何庫，所以它完全是自由而開源的。</p><p>Libimobiledevice 是一個面向對象的 API，它捆綁了許多便於你使用的終端工具。該庫支持蘋果從最早到其最新的型號的 iOS 設備。這是多年來研究和開發的結果。該項目中的應用包括 <code>usbmuxd</code>、<code>ideviceinstaller</code>、<code>idevicerestore</code>、<code>ifuse</code>、<code>libusbmuxd</code>、<code>libplist</code>、<code>libirecovery</code> 和 <code>libideviceactivation</code>。</p><h3 id="在-linux-上安裝-libimobiledevice" tabindex="-1">在 Linux 上安裝 Libimobiledevice <a class="header-anchor" href="#在-linux-上安裝-libimobiledevice" aria-label="Permalink to “在 Linux 上安裝 Libimobiledevice”">​</a></h3><p>在 Linux 上，你可能已經默認安裝了 <code>libimobiledevice</code>。你可以通過你的軟件包管理器或應用商店找到，或者通過運行項目中包含的一個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifuse --help</span></span></code></pre></div><p>你可以用你的包管理器安裝 <code>libimobiledevice</code>。例如，在 Fedora 或 CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install libimobiledevice ifuse usbmuxd</span></span></code></pre></div><p>在 Debian 和 Ubuntu 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install usbmuxd libimobiledevice6 libimobiledevice-utils</span></span></code></pre></div>',13)),n("p",null,[i[1]||(i[1]=e("或者，你可以從源代碼 ",-1)),s(t,{href:"https://github.com/libimobiledevice/libimobiledevice/"},{default:o(()=>[...i[0]||(i[0]=[e("下載",-1)])]),_:1}),i[2]||(i[2]=e(" 並安裝 ",-1)),i[3]||(i[3]=n("code",null,"libimobiledevice",-1)),i[4]||(i[4]=e("。",-1))]),i[25]||(i[25]=l('<h3 id="連接你的設備" tabindex="-1">連接你的設備 <a class="header-anchor" href="#連接你的設備" aria-label="Permalink to “連接你的設備”">​</a></h3><p>當你安裝了所需的軟件包，將你的 iOS 設備連接到你的電腦。</p><p>為你的 iOS 設備建立一個目錄作為掛載點。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/iPhone</span></span></code></pre></div><p>接下來，掛載設備：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifuse ~/iPhone</span></span></code></pre></div><p>你的設備提示你，是否信任你用來訪問它的電腦。</p><p><img src="https://opensource.com/sites/default/files/1trust_0.png" alt="iphone prompts to trust the computer"></p><p><em>圖 1：iPhone 提示你要信任該電腦。</em></p><p>信任問題解決後，你會在桌面上看到新的圖標。</p><p><img src="https://opensource.com/sites/default/files/2docks.png" alt="iphone icons appear on desktop"></p><p><em>圖 2：iPhone 的新圖標出現在桌面上。</em></p><p>點擊 “iPhone” 圖標，顯示出你的 iPhone 的文件夾結構。</p><p><img src="https://opensource.com/sites/default/files/2iphoneicon.png" alt="iphone folder structure displayed"></p><p><em>圖 3：顯示了 iPhone 的文件夾結構。</em></p><p>我通常最常訪問的文件夾是 <code>DCIM</code>，那裏存放着我的 iPhone 照片。有時我在寫文章時使用這些照片，有時有一些照片我想用 GIMP 等開源應用來增強。可以直接訪問這些圖片，而不是通過電子郵件把它們發給我自己，這是使用 <code>libimobiledevice</code> 工具的好處之一。我可以把這些文件夾中的任何一個複製到我的 Linux 電腦上。我也可以在 iPhone 上創建文件夾並刪除它們。</p><h3 id="發現更多" tabindex="-1">發現更多 <a class="header-anchor" href="#發現更多" aria-label="Permalink to “發現更多”">​</a></h3>',17)),n("p",null,[s(t,{href:"https://github.com/FunkyM"},{default:o(()=>[...i[5]||(i[5]=[e("Martin Szulecki",-1)])]),_:1}),i[7]||(i[7]=e(" 是該項目的首席開發者。該項目正在尋找開發者加入他們的 ",-1)),s(t,{href:"https://libimobiledevice.org/#community"},{default:o(()=>[...i[6]||(i[6]=[e("社區",-1)])]),_:1}),i[8]||(i[8]=e("。Libimobiledevice 可以改變你使用外設的方式，而無論你在什麼平台上。這是開源的又一次勝利，這意味着它是所有人的勝利。",-1))]),i[26]||(i[26]=n("hr",null,null,-1)),n("p",null,[i[10]||(i[10]=e("via: ",-1)),s(t,{href:"https://opensource.com/article/21/8/libimobiledevice-iphone-linux"},{default:o(()=>[...i[9]||(i[9]=[e("https://opensource.com/article/21/8/libimobiledevice-iphone-linux",-1)])]),_:1})]),n("p",null,[i[15]||(i[15]=e("作者：",-1)),s(t,{href:"https://opensource.com/users/don-watkins"},{default:o(()=>[...i[11]||(i[11]=[e("Don Watkins",-1)])]),_:1}),i[16]||(i[16]=e(" 選題：",-1)),s(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...i[12]||(i[12]=[e("lujun9972",-1)])]),_:1}),i[17]||(i[17]=e(" 譯者：",-1)),s(t,{href:"https://github.com/geekpi"},{default:o(()=>[...i[13]||(i[13]=[e("geekpi",-1)])]),_:1}),i[18]||(i[18]=e(" 校對：",-1)),s(t,{href:"https://github.com/wxy"},{default:o(()=>[...i[14]||(i[14]=[e("wxy",-1)])]),_:1})]),n("p",null,[i[21]||(i[21]=e("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...i[19]||(i[19]=[e("LCTT",-1)])]),_:1}),i[22]||(i[22]=e(" 原創編譯，",-1)),s(t,{href:"https://linux.cn/"},{default:o(()=>[...i[20]||(i[20]=[e("Linux中國",-1)])]),_:1}),i[23]||(i[23]=e(" 榮譽推出",-1))])])}const L=p(u,[["render",b]]);export{v as __pageData,L as default};
